PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT UNIQUE NOT NULL,
    password TEXT NOT NULL
);
CREATE TABLE submissions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    problem INTEGER NOT NULL,
    user INTEGER NOT NULL,
    source TEXT NOT NULL,
    status TEXT DEFAULT 'PENDING', time text,
    FOREIGN KEY (problem) REFERENCES problem(id),
    FOREIGN KEY (user) REFERENCES user(id)
);
CREATE TABLE answers (
  id integer primary key,
  imports text not null,
  body text not null
);
CREATE TABLE problems (
  id integer primary key,
  title text not null,
  statement text not null,
  template text not null,
  answer integer,
  contest integer, archived integer default 1 not null,
  foreign key (answer) references answers(id),
  foreign key (contest) references contest(id)
);
CREATE TABLE contests (
  id integer primary key,
  title text not null,
  start text not null,
  end text not null
);
CREATE TABLE website (
  id integer primary key,
  name TEXT,
  text TEXT
);
COMMIT;
